Submit Record To Form.code:
// Heads up: in the current adaptor source, submitRecord's POST is commented out,
// so this step won't send anything until the adaptor is fixed.
// Submit a record to an existing Magpi form.
// The payload is converted to an XML <form> document.
submitRecord({
  surveyid: $.configuration.surveyId, // the target form, e.g. '37479'
  data: {
    // keys must match the form's question names
    household_id: $.data.householdId,
    village: $.data.village,
    members_count: String($.data.membersCount),
  },
});

Fetch New Survey Submissions.code:
// Fetch submissions for a survey and forward each one.
// After the first run, state.lastSubmissionDate is used as the start date.
fetchSurveyData({
  surveyId: $.configuration.surveyId, // e.g. '37479'
  afterDate: '2026-10-01', // used only when there is no lastSubmissionDate
  postUrl: $.configuration.inboxUrl, // each submission is POSTed here as JSON
});

Fetch Submissions In Date Range.code:
// Fetch submissions between two dates and forward each one.
fetchSurveyData({
  surveyId: $.data.surveyId,
  afterDate: '2026-10-01', // start date
  beforeDate: '2026-10-31', // end date
  postUrl: $.configuration.inboxUrl,
});
